char *center(const char *s, int size, char pad) {
    if (s == NULL || size <= (int) strlen(s)) return (char *) s;
    int slen = (int) strlen(s);
    char *sb = (char *) malloc(size + 1);
    int len = 0;
    for (int i = 0; i < (size - slen) / 2; i++) {
        sb[len++] = pad;
    }
    memcpy(sb + len, s, slen);
    len += slen;
    while (len < size) {
        sb[len++] = pad;
    }
    sb[len] = '\0';
    return sb;
}

