    size_t total = 1;
    for (int i = 0; i < count; i++) {
        total += strlen(input[i]) + strlen(delimiter);
    }
    char *sb = (char *) malloc(total);
    size_t length = 0;
    for (int i = 0; i < count; i++) {
        size_t l = strlen(input[i]);
        memcpy(sb + length, input[i], l);
        length += l;
        size_t d = strlen(delimiter);
        memcpy(sb + length, delimiter, d);
