bool isAnagram(const char *a, const char *b) {
    if (strlen(a) != strlen(b)) {
        return false;
    }
    char *s1 = strdup(a);
    char *s2 = strdup(b);
    bool result = true;
    for (size_t i = 0; i < strlen(s2); i++) {
        char ch = s2[i];
        char *p = strchr(s1, ch);
        if (p == NULL) {
            result = false;
            break;
        }
        memmove(p, p + 1, strlen(p));
        p = strchr(s2, ch);
        memmove(p, p + 1, strlen(p));
    }
    free(s1);
    free(s2);
    return result;
}

