    if (s1.Length != s2.Length) {
        return false;
    }
    for (int i = 0; i < s2.Length; i++) {
        char ch = s2[i];
        int idx = s1.IndexOf(ch);
        if (idx < 0) {
            return false;
        }
        s1 = s1.Remove(idx, 1);
        s2 = s2.Remove(s2.IndexOf(ch), 1);
    }
    return true;
}

