public static IEnumerable < T > TakeLast < T > (this IEnumerable < T > input, int count) {
    if (count <= 0)
        yield break;
    if (input is IList < T >) {
        IList < T > list = (IList < T >) input;
        int last = list.Count;
        for (int index = Math.Max (0, last - count); index < last; index ++) {
            yield return list [index];
        }
        yield break;
    }
    Queue < T > window = new Queue < T > (count);
    foreach (T item in input) {
        if (window.Count == count)
            window.Dequeue ();
        window.Enqueue (item);
    }
    foreach (T item in window) {
        yield return item;
    }
}

